-- 0.9.0：本机评测运行（Promptfoo v3 结果原文）、本机评测任务与分片导入。
CREATE TABLE eval_runs(id TEXT PRIMARY KEY,name TEXT NOT NULL,origin TEXT NOT NULL,raw TEXT NOT NULL,stats TEXT NOT NULL,bytes INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE eval_tasks(id TEXT PRIMARY KEY,digest TEXT NOT NULL,state TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,host_calls INTEGER NOT NULL DEFAULT 0,run_id TEXT,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE eval_uploads(id TEXT NOT NULL,part INTEGER NOT NULL,total INTEGER NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(id,part));
